import {campPoints,candidates} from './radish-model.mjs?v=2';
const $=id=>document.getElementById(id),canvas=$('camp-map'),ctx=canvas.getContext('2d'),viewport=$('map-scroll');
const W=1960,H=1000,step=8,pad=20;canvas.width=W;canvas.height=H;
let layout,points=[],clues=[],origin={x:60,y:60},zoom=2.25,possible=[],background,dragging=false,directionMode='quick';
let renderScale=1,pan=null;const markerImage=new Image();markerImage.onload=()=>draw();markerImage.src=new URL('./radish-assets/point-marker.png',import.meta.url).href;
const project=(x,y)=>({x:pad+(x+y)*step,y:H/2+(x-y)*step/2});
function diamond(c,x,y,fill,stroke){const p=project(x,y);c.beginPath();c.moveTo(p.x,p.y-step/2);c.lineTo(p.x+step,p.y);c.lineTo(p.x,p.y+step/2);c.lineTo(p.x-step,p.y);c.closePath();if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=.45;c.stroke();}}
const scenery=new Image();scenery.src=new URL('./radish-assets/camp-map.webp',import.meta.url).href;
function buildBackground(){
 background=document.createElement('canvas');background.width=W;background.height=H;const c=background.getContext('2d');
 c.fillStyle='#52abc4';c.fillRect(0,0,W,H);
 if(scenery.complete&&scenery.naturalWidth)c.drawImage(scenery,0,0,W,H);
 const camp=new Set(points.map(p=>p.x+','+p.y));
 for(const p of points)diamond(c,p.x,p.y,'rgba(190,229,237,.18)','rgba(24,85,100,.3)');
 c.beginPath();
 for(const {x,y} of points){const p=project(x,y),top=[p.x,p.y-step/2],right=[p.x+step,p.y],bottom=[p.x,p.y+step/2],left=[p.x-step,p.y];
  for(const [dx,dy,a,b] of [[0,1,top,right],[1,0,right,bottom],[0,-1,bottom,left],[-1,0,left,top]])if(!camp.has((x+dx)+','+(y+dy))){c.moveTo(...a);c.lineTo(...b);}}
 c.strokeStyle='#faffef';c.lineWidth=2;c.stroke();
 for(const [x0,y0,x1,y1,special] of layout.regions)if(special)for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++)diamond(c,x,y,'#d7c19a','#9a825c');
}
const terrain=new Map(),terrainUndo=[],terrainKey='radish-camp-terrain-v1';
let mapMode='search',campCells=new Set(),terrainStroke=null;
function saveTerrain(){try{localStorage.setItem(terrainKey,JSON.stringify([...terrain]));$('terrain-status').textContent=terrain.size+' marked cells · saved on this device';}catch{$('terrain-status').textContent=terrain.size+' marked cells · available for this visit';}}
function terrainChanged(){ $('terrain-undo').disabled=!terrainUndo.length;draw(); }
function snapshotTerrain(){terrainUndo.push([...terrain]);if(terrainUndo.length>30)terrainUndo.shift();}
function setMapMode(mode){mapMode=mode;for(const b of document.querySelectorAll('[data-map-mode]'))b.setAttribute('aria-pressed',String(b.dataset.mapMode===mode));viewport.dataset.mode=mode;$('terrain-hint').textContent=mode==='search'?'Tap a search point. Hold and drag to move the map.':mode==='move'?'Hold and drag to move the map.':'Tap or drag to paint '+mode+'. Only camp cells can be edited.';}
for(const b of document.querySelectorAll('[data-map-mode]'))b.onclick=()=>setMapMode(b.dataset.mapMode);
$('terrain-undo').onclick=()=>{const previous=terrainUndo.pop();if(!previous)return;terrain.clear();for(const [key,value] of previous)terrain.set(key,value);saveTerrain();terrainChanged();};
$('terrain-reset').onclick=()=>{if(!terrain.size)return;snapshotTerrain();terrain.clear();saveTerrain();terrainChanged();};
function paintCell(x,y){const radius=Number($('terrain-brush').value);for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){const key=(x+dx)+','+(y+dy);if(campCells.has(key))terrain.set(key,mapMode);}}
function paintAt(e){const p=mapPoint(e);if(!p)return;const last=terrainStroke.last||p,n=Math.max(Math.abs(p.x-last.x),Math.abs(p.y-last.y),1);for(let i=0;i<=n;i++)paintCell(Math.round(last.x+(p.x-last.x)*i/n),Math.round(last.y+(p.y-last.y)*i/n));terrainStroke.last=p;terrainChanged();}
function drawTerrain(){for(const [key,type] of terrain){const [x,y]=key.split(',').map(Number);diamond(ctx,x,y,type==='ground'?'#b6cf87':'#70bfd4',type==='ground'?'#8aa45d':'#4497b0');}}
function draw(){if(!background)return;ctx.clearRect(0,0,W,H);ctx.drawImage(background,0,0);drawTerrain();if(clues.length)for(const p of possible)diamond(ctx,p.x,p.y,'rgba(255,196,62,.72)','#9d6b00');for(let i=0;i<clues.length;i++){const p=project(clues[i].x,clues[i].y);ctx.beginPath();ctx.arc(p.x,p.y,7,0,Math.PI*2);ctx.fillStyle='#6b6388';ctx.fill();ctx.fillStyle='white';ctx.font='bold 10px Poppins,sans-serif';ctx.textAlign='center';ctx.fillText(String(i+1),p.x,p.y+3);}const p=project(origin.x,origin.y);ctx.beginPath();ctx.ellipse(p.x,p.y,3*Math.SQRT2*step,3*Math.SQRT2*step/2,0,0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,.09)';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2/renderScale;ctx.stroke();const markerSize=22/renderScale;if(markerImage.complete&&markerImage.naturalWidth)ctx.drawImage(markerImage,p.x-markerSize/2,p.y-markerSize/2,markerSize,markerSize);else{ctx.fillStyle='#ffd457';ctx.strokeStyle='#74401a';ctx.lineWidth=2/renderScale;ctx.font='bold '+(20/renderScale)+'px Poppins,sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.strokeText('!',p.x,p.y);ctx.fillText('!',p.x,p.y);ctx.textBaseline='alphabetic';}if(clues.length){const c=clues.at(-1),s=project(c.x,c.y),a=c.angle*Math.PI/180;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x+Math.cos(a)*65,s.y-Math.sin(a)*65);ctx.strokeStyle='#785e8c';ctx.lineWidth=3;ctx.stroke();}}
function size(center=false){const scale=Math.min((viewport.clientWidth-2)/W,(viewport.clientHeight-2)/H)*zoom;renderScale=scale;canvas.style.width=Math.round(W*scale)+'px';canvas.style.height=Math.round(H*scale)+'px';canvas.style.margin=Math.max(0,(viewport.clientHeight-H*scale)/2)+'px auto';$('zoom-value').textContent=Math.round(zoom*100)+'%';$('zoom-out').disabled=zoom<=1;$('zoom-in').disabled=zoom>=12;if(center){const p=project(origin.x,origin.y);viewport.scrollLeft=p.x*scale-viewport.clientWidth/2;viewport.scrollTop=p.y*scale-viewport.clientHeight/2;}draw();}
function setOrigin(x,y,prompt=false){origin={x:Math.max(0,Math.min(119,Math.round(x))),y:Math.max(0,Math.min(119,Math.round(y)))};$('point-x').value=origin.x;$('point-y').value=origin.y;$('point-label').textContent=(origin.x===60&&origin.y===60?'Center selected':'Search point selected')+' · '+origin.x+', '+origin.y;draw();if(prompt){$('clue-title').textContent='What clue did you see?';document.querySelector('.clue-panel').dataset.ready='true';if(matchMedia('(max-width:740px)').matches)document.querySelector('.clue-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});$('angle').focus({preventScroll:true});}}
function mapPoint(e){if(!layout)return null;const r=canvas.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)return null;const wx=((e.clientX-r.left)*W/r.width-pad)/step,wy=((e.clientY-r.top)*H/r.height-H/2)/(step/2);return {x:Math.round((wx+wy)/2),y:Math.round((wx-wy)/2)};}
function selectMapPoint(e){const p=mapPoint(e);if(p)setOrigin(p.x,p.y,true);}
viewport.addEventListener('pointerdown',e=>{if(pan||terrainStroke||e.button!==0)return;viewport.setPointerCapture(e.pointerId);if(mapMode==='ground'||mapMode==='water'){snapshotTerrain();terrainStroke={id:e.pointerId,last:null};paintAt(e);return;}pan={id:e.pointerId,x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop,moved:false};});
viewport.addEventListener('pointermove',e=>{if(terrainStroke&&e.pointerId===terrainStroke.id){paintAt(e);e.preventDefault();return;}if(!pan||e.pointerId!==pan.id)return;const dx=e.clientX-pan.x,dy=e.clientY-pan.y;if(Math.hypot(dx,dy)>5)pan.moved=true;if(pan.moved){viewport.classList.add('is-dragging');viewport.scrollLeft=pan.left-dx;viewport.scrollTop=pan.top-dy;e.preventDefault();}});
function endPan(e){if(terrainStroke&&e.pointerId===terrainStroke.id){terrainStroke=null;saveTerrain();if(viewport.hasPointerCapture(e.pointerId))viewport.releasePointerCapture(e.pointerId);return;}if(!pan||e.pointerId!==pan.id)return;const select=e.type==='pointerup'&&!pan.moved&&mapMode==='search';pan=null;viewport.classList.remove('is-dragging');if(viewport.hasPointerCapture(e.pointerId))viewport.releasePointerCapture(e.pointerId);if(select)selectMapPoint(e);}
viewport.addEventListener('pointerup',endPan);viewport.addEventListener('pointercancel',endPan);viewport.addEventListener('lostpointercapture',()=>{if(terrainStroke){terrainStroke=null;saveTerrain();}pan=null;viewport.classList.remove('is-dragging');});
canvas.addEventListener('keydown',e=>{const d={ArrowRight:[1,1],ArrowLeft:[-1,-1],ArrowUp:[-1,1],ArrowDown:[1,-1]}[e.key];if(d){e.preventDefault();setOrigin(origin.x+d[0],origin.y+d[1]);}else if(e.key==='Enter'||e.key===' '){e.preventDefault();if(mapMode==='ground'||mapMode==='water'){snapshotTerrain();paintCell(origin.x,origin.y);saveTerrain();terrainChanged();}else if(mapMode==='search')setOrigin(origin.x,origin.y,true);}});
for(const id of ['point-x','point-y'])$(id).addEventListener('input',()=>{if($('point-x').value===''||$('point-y').value==='')return;setOrigin(Number($('point-x').value),Number($('point-y').value));});
const directions=[['→','Right',0],['↗','Up right',45],['↑','Up',90],['↖','Up left',135],['←','Left',180],['↙','Down left',225],['↓','Down',270],['↘','Down right',315]];
function setAllowance(value){$('tolerance').value=value;$('tolerance-value').textContent='±'+value+'°';}
function setAngle(v,mode='precise'){directionMode=mode;setAllowance(mode==='quick'?27.5:10);$('direction-hint').textContent=mode==='quick'?'Quick direction · broader estimate':'Compass direction · finer estimate';const a=((Math.round(v)%360)+360)%360;$('angle').value=a;$('dial-arrow').setAttribute('transform','rotate('+(-a)+' 80 80)');for(const b of $('directions').children)b.setAttribute('aria-pressed',String(Number(b.dataset.angle)===a));}
for(const [glyph,name,angle] of directions){const b=document.createElement('button');b.type='button';b.textContent=glyph;b.dataset.angle=angle;b.setAttribute('aria-label',name);b.addEventListener('click',()=>setAngle(angle,'quick'));$('directions').append(b);}
$('angle').addEventListener('input',()=>{if($('angle').value!=='')setAngle(Number($('angle').value));});
function dialPoint(e){const r=$('direction-dial').getBoundingClientRect();setAngle(Math.atan2(r.top+r.height/2-e.clientY,e.clientX-r.left-r.width/2)*180/Math.PI);}
$('direction-dial').addEventListener('pointerdown',e=>{dragging=true;$('direction-dial').setPointerCapture(e.pointerId);dialPoint(e);});$('direction-dial').addEventListener('pointermove',e=>{if(dragging)dialPoint(e);});for(const event of ['pointerup','pointercancel'])$('direction-dial').addEventListener(event,()=>{dragging=false;});
$('tolerance').addEventListener('input',()=>{directionMode='custom';$('direction-hint').textContent='Custom direction allowance';$('tolerance-value').textContent='±'+$('tolerance').value+'°';});
function update(){possible=candidates(points,clues);$('undo').disabled=!clues.length;$('map-status').textContent=clues.length?(possible.length?possible.length.toLocaleString()+' possible grids · '+clues.length+(clues.length===1?' clue':' clues'):'No overlap · check your clues'):'Start at the center or choose a search point.';$('result-count').classList.toggle('conflict',clues.length>0&&!possible.length);$('result-count').textContent=!clues.length?'Choose your first clue':possible.length?possible.length.toLocaleString()+' possible grids':'Clues do not overlap';$('result-message').textContent=!clues.length?'Choose your search point. If no radish was found, add its arrow and distance clue.':!possible.length?'Check the search points and arrow directions. Undo a clue and try a wider allowance, or clear clues if you found a radish.':possible.length===1?'One grid point matches these clues. Search nearby in the game; this is still an estimate.':'Yellow cells match every clue. Choose your next search point on the map, then add its arrow and indicator.';$('clue-history').replaceChildren();clues.forEach((c,i)=>{const li=document.createElement('li');li.append(document.createTextNode('Search '+(i+1)+' · '+c.x+', '+c.y));const detail=document.createElement('span');detail.textContent=c.angle+'° · '+({near:'Near',mid:'Medium',far:'Far'}[c.band])+' · ±'+c.tolerance+'°';li.append(detail);const b=document.createElement('button');b.type='button';b.textContent='Remove';b.setAttribute('aria-label','Remove clue '+(i+1));b.onclick=()=>{clues.splice(i,1);update();};li.append(b);$('clue-history').append(li);});draw();}
$('clue-form').addEventListener('submit',e=>{e.preventDefault();if(!layout)return;const band=new FormData(e.currentTarget).get('band');if(!band){$('form-error').textContent='Choose Near, Medium, or Far.';return;}if($('angle').value===''){ $('form-error').textContent='Match the arrow direction first.';return;}setOrigin(Number($('point-x').value),Number($('point-y').value));clues.push({...origin,angle:Number($('angle').value),band,direction:directionMode,tolerance:Number($('tolerance').value),margin:Number($('position-margin').value)});$('form-error').textContent='';update();$('clue-title').textContent='Choose the next search point';for(const radio of document.querySelectorAll('[name=band]'))radio.checked=false;if(matchMedia('(max-width:740px)').matches)$('result-count').scrollIntoView({block:'center'});});
$('undo').onclick=()=>{const c=clues.pop();if(c){setOrigin(c.x,c.y);setAngle(c.angle,c.direction||'precise');setAllowance(c.tolerance);}update();};
$('radish-found').onclick=()=>{setOrigin(Number($('point-x').value),Number($('point-y').value));clues=[];setAngle(0,'quick');for(const radio of document.querySelectorAll('[name=band]'))radio.checked=false;$('form-error').textContent='';$('clue-title').textContent='Start the next radish';document.querySelector('.clue-panel').dataset.ready='true';update();$('result-count').textContent='Ready for the next radish';$('result-message').textContent='Previous clues cleared. Start your next search from '+origin.x+', '+origin.y+', or select a different point on the map.';$('map-status').textContent='Fresh search · starting at '+origin.x+', '+origin.y;size(true);};
$('clear').onclick=()=>{clues=[];setOrigin(60,60);setAngle(0,'quick');for(const radio of document.querySelectorAll('[name=band]'))radio.checked=false;$('form-error').textContent='';$('clue-title').textContent='Where did you search?';document.querySelector('.clue-panel').dataset.ready='false';update();size(true);};
$('zoom-in').onclick=()=>{zoom=Math.min(12,zoom+1);size(true);};$('zoom-out').onclick=()=>{zoom=Math.max(1,zoom-1);size(true);};$('fit').onclick=()=>{zoom=2.25;size(true);};new ResizeObserver(()=>size()).observe(viewport);setAngle(0,'quick');
try{const response=await fetch(new URL('./radish-layout.json?v=2',import.meta.url));if(!response.ok)throw Error();layout=await response.json();points=campPoints(layout);campCells=new Set(points.map(p=>p.x+','+p.y));try{const saved=JSON.parse(localStorage.getItem(terrainKey)||'[]');if(Array.isArray(saved))for(const entry of saved)if(Array.isArray(entry)&&campCells.has(entry[0])&&['ground','water'].includes(entry[1]))terrain.set(entry[0],entry[1]);}catch{}saveTerrain();setMapMode('search');await scenery.decode().catch(()=>{});buildBackground();update();size(true);}catch{$('result-count').textContent='Map unavailable';$('result-message').textContent='Please reload to try again.';$('clue-form').querySelector('button[type=submit]').disabled=true;}
